-- ScrapFlow local PostgreSQL schema. Run once in DBeaver against scrap_business.
-- Spring Boot does not create or alter tables automatically.
create extension if not exists pgcrypto;
create table if not exists profiles (id uuid primary key,email text not null unique,password_hash text not null,full_name text not null,phone text,account_type text not null check(account_type in ('HOME_SELLER','BULK_SELLER','CLIENT_ADMIN','PICKUP_STAFF','SUPER_ADMIN')),account_status text not null default 'ACTIVE' check(account_status in ('ACTIVE','SUSPENDED','PENDING')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists clients (id uuid primary key,name text not null,slug text not null unique,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists client_memberships (id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id) on delete cascade,client_id uuid not null references clients(id) on delete cascade,membership_role text not null,is_active boolean not null default true,unique(user_id,client_id));
create table if not exists seller_profiles (user_id uuid primary key references profiles(id) on delete cascade,business_name text,billing_address jsonb,updated_at timestamptz not null default now());
create table if not exists scrap_categories (id uuid primary key,client_id uuid not null references clients(id) on delete cascade,name text not null,is_active boolean not null default true,unique(client_id,name));
create table if not exists scrap_rates (id uuid primary key,client_id uuid not null references clients(id) on delete cascade,category_id uuid not null references scrap_categories(id) on delete restrict,rate_per_kg numeric(12,2) not null check(rate_per_kg>=0),effective_from timestamptz not null default now(),is_active boolean not null default true);
create table if not exists pickup_requests (id uuid primary key,client_id uuid not null references clients(id),seller_id uuid not null references profiles(id),estimated_quantity numeric(12,2) not null check(estimated_quantity>0),actual_weight numeric(12,2),pickup_address jsonb not null,preferred_date date not null,preferred_time text,status text not null default 'REQUESTED' check(status in ('REQUESTED','CONFIRMED','ASSIGNED','PICKED_UP','COMPLETED','CANCELLED')),final_amount numeric(12,2),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists pickup_request_items (id uuid primary key,pickup_request_id uuid not null references pickup_requests(id) on delete cascade,category_id uuid not null references scrap_categories(id),estimated_quantity numeric(12,2) not null check(estimated_quantity>0),actual_weight numeric(12,2));
create table if not exists pickup_assignments (pickup_request_id uuid primary key references pickup_requests(id) on delete cascade,staff_user_id uuid not null references profiles(id),assigned_by uuid not null references profiles(id),assigned_at timestamptz not null default now());
create index if not exists pickup_requests_seller_idx on pickup_requests(seller_id,created_at desc);
create index if not exists pickup_requests_client_idx on pickup_requests(client_id,status,created_at desc);
create or replace view current_scrap_rates as select r.id,r.client_id,r.category_id,c.name as category_name,r.rate_per_kg,r.effective_from from scrap_rates r join scrap_categories c on c.id=r.category_id where r.is_active=true;
insert into clients(id,name,slug,is_active) values(gen_random_uuid(),'Default Scrap Business','default-scrap-business',true) on conflict(slug) do nothing;
